        [UnityTest] public IEnumerator BloomPerView() => Run("bloom", f => f.AddBloom());
        [UnityTest] public IEnumerator WorldSpaceUGUI() => Run("ugui-world", f => f.AddWorldUi());
        [UnityTest] public IEnumerator ScreenSpaceCameraUGUI() => Run("ugui-camera", f => f.AddCameraUi());
        [UnityTest] public IEnumerator UIToolkitTargetTexture() => Run("uitk-target", f => f.AddUiToolkit());
        [UnityTest] public IEnumerator MeshParticleSimulationOnce() => Run("mesh-particles", f => f.AddMeshParticles());
        [UnityTest] public IEnumerator MeshParticleLiveSimulation() => Run("mesh-particles-live", f => f.AddMeshParticles(true));

        IEnumerator Run(string name, Action<Fixture> add)
        {
            Fixture fixture = null;
            try { fixture = new Fixture(name); fixture.Setup(); add(fixture); fixture.RefreshScope(); yield return null; yield return null; fixture.Toggle(false); yield return null; yield return null; fixture.Capture(false); fixture.Toggle(true); yield return null; yield return null; fixture.Capture(true); fixture.AssertChanged(); if (name == "transparent-lit") fixture.AssertTransparentAlphaBlend(); }
            finally { if (fixture != null) fixture.Dispose(); }
        }

