                oldDefault = GraphicsSettings.defaultRenderPipeline; oldQuality = QualitySettings.renderPipeline; pipeline = ScriptableObject.CreateInstance<HDRenderPipelineAsset>(); GraphicsSettings.defaultRenderPipeline = pipeline; QualitySettings.renderPipeline = pipeline;
                root = new GameObject("HDRPCompatibility_" + name); owned.Add(root); GameObject cameraObject = new GameObject("QuiltCamera"); cameraObject.transform.SetParent(root.transform, false); camera = cameraObject.AddComponent<Camera>(); camera.enabled = false; camera.clearFlags = CameraClearFlags.SolidColor; camera.backgroundColor = Color.black; camera.fieldOfView = 50f; var data = camera.gameObject.AddComponent<HDAdditionalCameraData>(); data.volumeLayerMask = 1 << GraphicsFixtureScope.Layer; data.clearColorMode = HDAdditionalCameraData.ClearColorMode.Color; data.backgroundColorHDR = Color.black; quilt = cameraObject.AddComponent<QuiltRenderer>(); quilt.sourceCamera = camera; quilt.GuardBehaviour = cameraObject.AddComponent<HdrpQuiltCamera>(); quilt.settings.quiltWidth = W * 4; quilt.settings.quiltHeight = H * 2; quilt.settings.columns = 4; quilt.settings.rows = 2; quilt.settings.views = 8; quilt.settings.viewAspect = 1f; quilt.settings.cameraDistance = 3f; quilt.settings.fieldOfView = 50f; quilt.settings.viewCone = 30f;
                GameObject lightObject = new GameObject("HDRPDirectional"); lightObject.transform.SetParent(root.transform, false); var light = lightObject.AddComponent<Light>(); light.type = LightType.Directional; light.intensity = 10f; lightObject.AddComponent<HDAdditionalLightData>(); owned.Add(lightObject); AddCube("BaseLit", new Vector3(0f, 0f, 3f), Color.white);
                GameObject volumeObject = new GameObject("HDRPFixedExposure"); volumeObject.transform.SetParent(root.transform, false); var volume = volumeObject.AddComponent<Volume>(); volume.isGlobal = true; volume.priority = 10f; var profile = ScriptableObject.CreateInstance<VolumeProfile>(); var exposure = profile.Add<Exposure>(true); exposure.mode.value = ExposureMode.Fixed; exposure.mode.overrideState = true; exposure.fixedExposure.value = 4f; exposure.fixedExposure.overrideState = true; var motionBlur = profile.Add<MotionBlur>(true); motionBlur.active = true; motionBlur.intensity.value = 0f; motionBlur.intensity.overrideState = true; var reflection = profile.Add<ScreenSpaceReflection>(true); reflection.enabled.value = false; reflection.enabled.overrideState = true; volume.sharedProfile = profile; owned.Add(volumeObject); owned.Add(profile);
