            public void RefreshScope() { scope.Apply(camera); }
            public void Capture(bool enabled) { if (particle != null) { particleTime = particle.time; particleCount = particle.particleCount; } quilt.RenderQuilt(); if (particle != null) { Assert.AreEqual(particleTime, particle.time, 0.0001f); Assert.AreEqual(particleCount, particle.particleCount); if (particleLive) Assert.IsTrue(particle.isPlaying); } Texture2D image = Read(quilt.QuiltTexture); if (enabled) after = image; else before = image; SaveImage(image, enabled ? "after" : "before"); if (uiTexture != null && enabled) AssertUi(); }
            public void AssertTransparentAlphaBlend() { Assert.IsNotNull(transparentMaterial, "transparent material is unavailable"); transparentMaterial.color = new Color(1f, 0f, 1f, 1f); quilt.RenderQuilt(); alphaFull = Read(quilt.QuiltTexture); SaveImage(alphaFull, "alpha1"); Color[] half = after.GetPixels(), full = alphaFull.GetPixels(); for (int view = 0; view < 8; ++view) { RectInt tile = quilt.settings.GetLayout().GetTile(view); int changed = 0; for (int y = tile.y; y < tile.yMax; ++y) for (int x = tile.x; x < tile.xMax; ++x) { int i = y * after.width + x; if (Mathf.Abs(half[i].r - full[i].r) + Mathf.Abs(half[i].g - full[i].g) + Mathf.Abs(half[i].b - full[i].b) > 0.01f) changed++; } Assert.Greater(changed, 20, "HDRP transparent alpha did not change tile " + view); } transparentMaterial.color = new Color(1f, 0f, 1f, 0.5f); }
