            void AssertUi() { Texture2D image = Read(uiTexture); Color pixel = image.GetPixel(image.width / 2, image.height / 2); UnityEngine.Object.DestroyImmediate(image); Assert.Greater(pixel.r, 0.2f); Assert.Greater(pixel.b, 0.2f); }
            void SaveImage(Texture2D image, string suffix) { string directory = Path.GetFullPath(Path.Combine(Application.dataPath, "..", "..", "..", "..", ".local", "graphics-compatibility")); Directory.CreateDirectory(directory); File.WriteAllBytes(Path.Combine(directory, "hdrp-" + name + "-" + suffix + ".png"), image.EncodeToPNG()); }
            public void AssertChanged() { Color[] a = before.GetPixels(), b = after.GetPixels(); string path = Path.GetFullPath(Path.Combine(Application.dataPath, "..", "..", "..", "..", ".local", "graphics-compatibility", "hdrp-" + name + "-diagnostic.txt")); Directory.CreateDirectory(Path.GetDirectoryName(path)); using (StreamWriter writer = new StreamWriter(path, false)) { for (int view = 0; view < 8; ++view) { RectInt tile = quilt.settings.GetLayout().GetTile(view); int changed = 0; for (int y = tile.y; y < tile.yMax; ++y) for (int x = tile.x; x < tile.xMax; ++x) { int i = y * before.width + x; if (Mathf.Abs(a[i].r - b[i].r) + Mathf.Abs(a[i].g - b[i].g) + Mathf.Abs(a[i].b - b[i].b) > 0.01f) changed++; } writer.WriteLine("tile=" + view + " changed=" + changed); Assert.Greater(changed, 20, "HDRP feature did not change tile " + view); } } }
            public void Dispose() { RenderTexture.active = null; if (before != null) UnityEngine.Object.DestroyImmediate(before); if (after != null) UnityEngine.Object.DestroyImmediate(after); if (alphaFull != null) UnityEngine.Object.DestroyImmediate(alphaFull); if (uiTexture != null) { uiTexture.Release(); UnityEngine.Object.DestroyImmediate(uiTexture); } foreach (var item in owned) if (item != null) UnityEngine.Object.DestroyImmediate(item); scope?.Dispose(); GraphicsSettings.defaultRenderPipeline = oldDefault; QualitySettings.renderPipeline = oldQuality; if (pipeline != null) UnityEngine.Object.DestroyImmediate(pipeline); }
            public void AddTransparent() { AddMesh("HDRP/Lit", out feature, out var material); transparentMaterial = material; material.SetFloat("_SurfaceType", 1f); material.SetFloat("_ZWrite", 0f); material.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha); material.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha); material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT"); material.renderQueue = (int)RenderQueue.Transparent; material.color = new Color(1f, 0f, 1f, 0.5f); feature.transform.localPosition = new Vector3(0f, 0f, 2.2f); toggle = enabled => feature.SetActive(enabled); }
            public void AddBloom() { AddMesh("HDRP/Lit", out feature, out var material); material.EnableKeyword("_EMISSION"); material.SetColor("_EmissiveColor", new Color(5f, 2f, 5f, 1f)); feature.transform.localPosition = new Vector3(0f, 0f, 2.2f); GameObject volumeObject = new GameObject("BloomVolume"); volumeObject.transform.SetParent(root.transform, false); bloomVolume = volumeObject.AddComponent<Volume>(); bloomVolume.isGlobal = true; var profile = ScriptableObject.CreateInstance<VolumeProfile>(); var bloom = profile.Add<UnityEngine.Rendering.HighDefinition.Bloom>(true); bloom.intensity.value = 3f; bloom.threshold.value = 0.5f; bloomVolume.sharedProfile = profile; owned.Add(volumeObject); owned.Add(profile); toggle = enabled => bloomVolume.enabled = enabled; }
            public void AddWorldUi() { AddUiCanvas(RenderMode.WorldSpace); }
            public void AddCameraUi() { AddUiCanvas(RenderMode.ScreenSpaceCamera); }
            void AddUiCanvas(RenderMode mode) { feature = new GameObject("HDRPUI"); feature.transform.SetParent(root.transform, false); var canvas = feature.AddComponent<Canvas>(); canvas.renderMode = mode; canvas.worldCamera = camera; canvas.planeDistance = quilt.settings.cameraDistance; feature.transform.localPosition = new Vector3(0f, 0f, 2.2f); feature.transform.localScale = mode == RenderMode.WorldSpace ? Vector3.one * 0.01f : Vector3.one; feature.GetComponent<RectTransform>().sizeDelta = new Vector2(256f, 192f); var imageObject = new GameObject("Image"); imageObject.transform.SetParent(feature.transform, false); var rect = imageObject.AddComponent<RectTransform>(); rect.anchorMin = Vector2.zero; rect.anchorMax = Vector2.one; rect.sizeDelta = Vector2.zero; var image = imageObject.AddComponent<UnityEngine.UI.Image>(); image.color = Color.magenta; Canvas.ForceUpdateCanvases(); owned.Add(feature); toggle = enabled => feature.SetActive(enabled); }
            public void AddUiToolkit() { feature = new GameObject("HDRPUIToolkit"); feature.transform.SetParent(root.transform, false); var document = feature.AddComponent<UnityEngine.UIElements.UIDocument>(); var panel = ScriptableObject.CreateInstance<UnityEngine.UIElements.PanelSettings>(); uiTexture = new RenderTexture(256, 192, 0, RenderTextureFormat.ARGB32); uiTexture.Create(); panel.targetTexture = uiTexture; panel.referenceResolution = new Vector2Int(256, 192); panel.scaleMode = UnityEngine.UIElements.PanelScaleMode.ConstantPixelSize; document.panelSettings = panel; document.rootVisualElement.style.width = 256f; document.rootVisualElement.style.height = 192f; var element = new UnityEngine.UIElements.VisualElement(); element.style.width = 256f; element.style.height = 192f; element.style.backgroundColor = new Color(0.9f, 0f, 0.9f, 1f); document.rootVisualElement.Add(element); AddQuad("HDRP/Lit", out uiPlane, out var material); uiPlane.transform.localPosition = new Vector3(0f, 0f, 2.0f); material.SetTexture("_BaseColorMap", uiTexture); owned.Add(feature); owned.Add(panel); owned.Add(uiTexture); toggle = enabled => uiPlane.SetActive(enabled); }
